-- AffiliateOS schema v0.1. Apply once to a new Supabase project.
create extension if not exists pgcrypto;
create table public.workspaces(id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, workspace_id uuid not null references public.workspaces(id), name text not null, email text, role text not null default 'Viewer' check(role in ('Admin','Affiliate Manager','Analyst','Viewer')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create function public.current_workspace() returns uuid language sql stable security definer set search_path = '' as $$ select workspace_id from public.profiles where id=auth.uid() $$;
create function public.current_role() returns text language sql stable security definer set search_path = '' as $$ select role from public.profiles where id=auth.uid() $$;
revoke all on function public.current_workspace(), public.current_role() from public;
grant execute on function public.current_workspace(), public.current_role() to authenticated;
create table public.clients(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), name text not null check(length(trim(name))>0), industry text, owner text, status text not null default 'Active', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.brands(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), name text not null, client_id uuid not null, category text, status text not null default 'Active', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.products(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), name text not null, sku text not null, brand_id uuid not null, category text, status text not null default 'Active', image_path text, unique(workspace_id,sku), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.campaigns(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), name text not null, brand_id uuid not null, marketplace text not null check(marketplace in ('TikTok','Shopee','Multi-platform')), objective text, start_date date not null, end_date date not null, target_gmv numeric(18,2) default 0 check(target_gmv>=0), target_orders integer default 0 check(target_orders>=0), owner text, status text not null default 'Draft', check(end_date>=start_date), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.creators(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), name text not null, category text, email text, tags text, notes text, last_activity date, status text not null default 'Active', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.creator_tags(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), creator_id uuid not null, label text not null, unique(workspace_id,creator_id,label), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.campaign_products(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), campaign_id uuid not null, product_id uuid not null, unique(workspace_id,campaign_id,product_id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.campaign_creators(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), campaign_id uuid not null, creator_id uuid not null, status text default 'Active', unique(workspace_id,campaign_id,creator_id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.import_jobs(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), marketplace text not null check(marketplace in ('TikTok','Shopee')), original_filename text not null, uploaded_by uuid not null references auth.users(id), status text not null default 'Ready for review', row_count integer not null default 0, successful_rows integer not null default 0, failed_rows integer not null default 0, mapping jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.import_files(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), import_job_id uuid not null, storage_path text not null, original_filename text not null, size_bytes bigint not null, mime_type text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.import_column_mappings(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), import_job_id uuid not null, marketplace text not null check(marketplace in ('TikTok','Shopee')), mapping jsonb not null, schema_version text not null default '0.1', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.raw_import_rows(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), import_job_id uuid not null, row_number integer not null, payload jsonb not null, unique(workspace_id,import_job_id,row_number), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.import_errors(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), import_job_id uuid not null, row_number integer, message text not null, severity text not null default 'error', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.tasks(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), name text not null, client_id uuid, campaign_id uuid, creator_id uuid, due_date date not null, priority text default 'Medium' check(priority in ('Low','Medium','High','Urgent')), owner text, status text default 'To Do' check(status in ('To Do','In Progress','Done')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.reports(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), name text not null, client_id uuid, campaign_id uuid, marketplace text check(marketplace in ('TikTok','Shopee','Multi-platform')), period_start date, period_end date, created_by uuid references auth.users(id), status text default 'Draft', file_path text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.activity_logs(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), user_id uuid references auth.users(id), actor_name text, action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.tiktok_accounts(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), creator_id uuid not null, username text not null, display_name text, profile_url text, followers bigint not null default 0 check(followers>=0), status text default 'Active', unique(workspace_id,username), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.tiktok_product_mappings(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), product_id uuid not null, tiktok_product_id text not null, unique(workspace_id,product_id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.tiktok_performance_daily(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), date date not null, account_id uuid not null, campaign_id uuid not null, product_id uuid, gmv numeric(18,2) not null default 0 check(gmv>=0), orders integer not null default 0 check(orders>=0), units_sold integer not null default 0 check(units_sold>=0), commission numeric(18,2) not null default 0 check(commission>=0), source_import_id uuid, video_count integer default 0 check(video_count>=0), live_count integer default 0 check(live_count>=0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.shopee_accounts(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), creator_id uuid not null, username text not null, display_name text, profile_url text, followers bigint not null default 0 check(followers>=0), status text default 'Active', unique(workspace_id,username), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.shopee_product_mappings(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), product_id uuid not null, shopee_item_id text not null, unique(workspace_id,product_id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.shopee_performance_daily(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), date date not null, account_id uuid not null, campaign_id uuid not null, product_id uuid, gmv numeric(18,2) not null default 0 check(gmv>=0), orders integer not null default 0 check(orders>=0), units_sold integer not null default 0 check(units_sold>=0), commission numeric(18,2) not null default 0 check(commission>=0), source_import_id uuid, clicks integer default 0 check(clicks>=0), conversion_rate numeric(8,6) default 0 check(conversion_rate between 0 and 1), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.tiktok_content(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), account_id uuid not null, campaign_id uuid, product_id uuid, source_import_id uuid, content_url text, content_type text check(content_type in ('Video','Live')), published_at timestamptz, title text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
create table public.shopee_affiliate_activity(id uuid primary key default gen_random_uuid(), workspace_id uuid not null default public.current_workspace() references public.workspaces(id), account_id uuid not null, campaign_id uuid, product_id uuid, source_import_id uuid, date date not null, clicks integer default 0, orders integer default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,id));
