-- App roles are enforced in PostgreSQL as well as route handlers.
alter table public.workspaces enable row level security;
alter table public.profiles enable row level security;
create policy workspace_read on public.workspaces for select to authenticated using(id=public.current_workspace());
create policy profile_read on public.profiles for select to authenticated using(workspace_id=public.current_workspace());
create policy profile_edit_self on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid() and workspace_id=public.current_workspace());
revoke all on public.profiles,public.workspaces from anon,authenticated;
grant select on public.profiles,public.workspaces to authenticated;
grant update(name) on public.profiles to authenticated;
alter table public.clients enable row level security;
revoke all on public.clients from anon,authenticated;
grant select on public.clients to authenticated;
create policy workspace_read on public.clients for select to authenticated using(workspace_id=public.current_workspace());
grant insert,update,delete on public.clients to authenticated;
create policy workspace_insert on public.clients for insert to authenticated with check(workspace_id=public.current_workspace() and public.current_role() in ('Admin'));
create policy workspace_update on public.clients for update to authenticated using(workspace_id=public.current_workspace() and public.current_role() in ('Admin')) with check(workspace_id=public.current_workspace() and public.current_role() in ('Admin'));
create policy workspace_delete on public.clients for delete to authenticated using(workspace_id=public.current_workspace() and public.current_role() in ('Admin'));
