create function public.touch_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end $$;
create function public.audit_record() returns trigger language plpgsql security definer set search_path='' as $$
declare r jsonb; actor text;
begin
  if TG_OP='DELETE' then r=to_jsonb(old); else r=to_jsonb(new); end if;
  select name into actor from public.profiles where id=auth.uid();
  insert into public.activity_logs(workspace_id,user_id,actor_name,action,entity_type,entity_id,metadata)
  values((r->>'workspace_id')::uuid,auth.uid(),coalesce(actor,'System'),coalesce(r->>'name',TG_TABLE_NAME)||' '||lower(TG_OP),TG_TABLE_NAME,(r->>'id')::uuid,jsonb_build_object('operation',TG_OP));
  if TG_OP='DELETE' then return old; else return new; end if;
end $$;
create trigger touch_updated_at before update on public.clients for each row execute function public.touch_updated_at();
create trigger audit_change after insert or update or delete on public.clients for each row execute function public.audit_record();
