-- Raw imports are staged atomically; no analytics table is written here.
create function public.stage_import(job jsonb, file_metadata jsonb, raw_rows jsonb, validation_errors jsonb) returns uuid language plpgsql security invoker set search_path='' as $$
declare jid uuid := (job->>'id')::uuid; wid uuid := public.current_workspace();
begin
  if public.current_role() not in ('Admin','Affiliate Manager') then raise exception 'Insufficient access'; end if;
  if jsonb_array_length(raw_rows)>10000 then raise exception 'Row limit exceeded'; end if;
  insert into public.import_jobs(id,workspace_id,marketplace,original_filename,uploaded_by,status,row_count,successful_rows,failed_rows,mapping)
  values(jid,wid,job->>'marketplace',job->>'filename',auth.uid(),job->>'status',jsonb_array_length(raw_rows),0,(job->>'failed_rows')::integer,job->'mapping');
  insert into public.import_files(workspace_id,import_job_id,storage_path,original_filename,size_bytes,mime_type)
  values(wid,jid,file_metadata->>'path',job->>'filename',(file_metadata->>'size')::bigint,file_metadata->>'type');
  insert into public.import_column_mappings(workspace_id,import_job_id,marketplace,mapping) values(wid,jid,job->>'marketplace',job->'mapping');
  insert into public.raw_import_rows(workspace_id,import_job_id,row_number,payload) select wid,jid,ordinality::integer+1,value from jsonb_array_elements(raw_rows) with ordinality;
  insert into public.import_errors(workspace_id,import_job_id,message) select wid,jid,value #>> '{}' from jsonb_array_elements(validation_errors);
  return jid;
end $$;
revoke all on function public.stage_import(jsonb,jsonb,jsonb,jsonb) from public;
grant execute on function public.stage_import(jsonb,jsonb,jsonb,jsonb) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('workspace-files','workspace-files',false,5242880,array['text/csv','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/octet-stream']) on conflict(id) do nothing;
create policy workspace_files_read on storage.objects for select to authenticated using(bucket_id='workspace-files' and (storage.foldername(name))[1]=public.current_workspace()::text);
create policy workspace_files_insert on storage.objects for insert to authenticated with check(bucket_id='workspace-files' and (storage.foldername(name))[1]=public.current_workspace()::text and public.current_role() in ('Admin','Affiliate Manager'));
create policy workspace_files_delete on storage.objects for delete to authenticated using(bucket_id='workspace-files' and (storage.foldername(name))[1]=public.current_workspace()::text and public.current_role() in ('Admin','Affiliate Manager'));

-- Prevent cross-marketplace provenance or campaign attribution.
create function public.validate_marketplace_source() returns trigger language plpgsql set search_path='' as $$
declare expected text; source_market text; campaign_market text;
begin
  expected := case when TG_TABLE_NAME like 'tiktok_%' then 'TikTok' else 'Shopee' end;
  if new.source_import_id is not null then
    select marketplace into source_market from public.import_jobs where id=new.source_import_id and workspace_id=new.workspace_id;
    if source_market is distinct from expected then raise exception 'Source import marketplace does not match performance table'; end if;
  end if;
  select marketplace into campaign_market from public.campaigns where id=new.campaign_id and workspace_id=new.workspace_id;
  if campaign_market not in (expected,'Multi-platform') then raise exception 'Campaign marketplace does not match performance table'; end if;
  return new;
end $$;
create trigger validate_market before insert or update on public.tiktok_performance_daily for each row execute function public.validate_marketplace_source();
create trigger validate_market before insert or update on public.shopee_performance_daily for each row execute function public.validate_marketplace_source();
create unique index tiktok_username_case_insensitive on public.tiktok_accounts(workspace_id,lower(username));
create unique index shopee_username_case_insensitive on public.shopee_accounts(workspace_id,lower(username));
